#!/usr/bin/env python3
"""Generate fail-visible Mono door functions from monodis --implmap dumps.

Inputs (in third_party/mono-bridges/):
  celeste.implmap / steamworks.implmap — monodis --implmap dumps of
    Celeste.exe / Steamworks.NET.dll, kept in this dir
  real-fmod.txt / real-steam.txt — native names with REAL implementations
    in mono_fmod_door.cpp / mono_steam_door.cpp

Outputs: gen/gen_fmod_failvisible.inc, gen/gen_steam_failvisible.inc,
included by the door .cpp files.

Every P/Invoke the game declares gets a symbol, so Mono's lazy binder never
throws EntryPointNotFoundException for an uncalled function. Functions the
real bridges do NOT implement get a FAIL-VISIBLE function: a loud one-time
log line naming the function, and a FAILURE return (FMOD_ERR_UNSUPPORTED=64
for FMOD_RESULT, false for bool, NULL for pointers, 0 for numerics).
Nothing here pretends success — that is the difference from the old
spike-parity stubs, which returned FMOD_OK and fake handles.

A generated function is declared f(void) and ignores its arguments: on
SysV x86-64 the caller cleans the stack and the return value travels in
RAX/XMM0, so a zero-arg callee is ABI-compatible with any caller. The only
exceptions are struct-by-value returns (the three Steam Controller data
functions), which are hand-written in mono_steam_door.cpp with the correct
SysV struct-return ABI and therefore MUST be in real-steam.txt.
"""
import re
import sys
from pathlib import Path

HERE = Path(__file__).resolve().parent

IMPLMAP_RE = re.compile(
    r"^\d+: (.*?) (?:class |valuetype )?[\w\.]+::\w+\(.*\) \d+ \((\S+) (\S+)\)$"
)

# managed return type -> (C return type, failure expression, failure label)
RET_MAP = {
    "valuetype FMOD.RESULT": ("int", "64", "FMOD_ERR_UNSUPPORTED"),
    "bool": ("int", "0", "false"),
    "void": ("void", None, "void"),
    "native int": ("void *", "NULL", "NULL"),
    "int32": ("int", "0", "0"),
    "unsigned int32": ("unsigned int", "0", "0"),
    "int64": ("long long", "0", "0"),
    "unsigned int64": ("unsigned long long", "0", "0"),
    "int16": ("int", "0", "0"),
    "unsigned int8": ("int", "0", "0"),
    "float32": ("float", "0.0f", "0"),
    "float64": ("double", "0.0", "0"),
}
STRUCT_RET_RE = re.compile(r"^valuetype Steamworks\.\w+_t$")  # Steam *_t types are structs
ENUM_RE = re.compile(r"^valuetype Steamworks\.\w+$")          # any other Steam valuetype is an enum (int-sized)

HEADER = """// GENERATED by gen-failvisible.py from {src} — do not edit by hand.
// Fail-visible door functions: loud one-time log + FAILURE return.
// Real implementations live in {door} (see real-{tag}.txt).
// Included by {door}; <cstdio> must be included before this file.
"""


def parse_implmap(path):
    """Return {native_name: (rettype, module, managed_sig)}."""
    entries = {}
    for line in Path(path).read_text().splitlines():
        m = IMPLMAP_RE.match(line.strip())
        if not m:
            continue
        rettype, name, module = m.group(1), m.group(2), m.group(3)
        if name in entries:
            prev = entries[name]
            if prev[0] != rettype:
                raise SystemExit(
                    f"CONFLICT: {name} has return types {prev[0]!r} and {rettype!r}"
                )
            continue
        entries[name] = (rettype, module, line.strip())
    return entries


def c_return(rettype):
    if rettype in RET_MAP:
        return RET_MAP[rettype]
    if STRUCT_RET_RE.match(rettype):
        return None  # hand-written (struct-by-value ABI)
    if ENUM_RE.match(rettype):
        return ("int", "0", "0")
    raise SystemExit(f"UNKNOWN return type: {rettype!r}")


def generate(implmap, real_file, out_path, tag, door):
    entries = parse_implmap(HERE / implmap)
    real = {
        ln.strip()
        for ln in (HERE / real_file).read_text().splitlines()
        if ln.strip() and not ln.startswith("#")
    }
    # every real entry must name a real implmap entry (else dead code)
    for o in sorted(real):
        if o not in entries:
            raise SystemExit(f"REAL NOT IN IMPLMAP: {o} ({real_file})")
    gen = HERE / "gen"
    gen.mkdir(exist_ok=True)
    lines = [HEADER.format(src=implmap, door=door, tag=tag)]
    n_gen = n_real = 0
    for name in sorted(entries):
        rettype, module, sig = entries[name]
        if name in real:
            n_real += 1
            continue
        cr = c_return(rettype)
        if cr is None:
            raise SystemExit(
                f"STRUCT RETURN not implemented for real: {name} ({rettype}) "
                f"— add it to {real_file} with a hand-written door"
            )
        ctype, val, label = cr
        lines.append(f"/* {sig} */")
        lines.append(f"extern \"C\" {ctype} {name}(void) {{")
        lines.append("  static int logged = 0;")
        lines.append("  if (!logged) {")
        lines.append("    logged = 1;")
        lines.append(
            f"    fprintf(stderr, \"[trt] mono-door: {name} is NOT "
            f"IMPLEMENTED (fail-visible, returning {label})\\n\");"
        )
        lines.append("  }")
        if ctype != "void":
            lines.append(f"  return {val};")
        lines.append("}")
        lines.append("")
        n_gen += 1
    (gen / out_path).write_text("\n".join(lines))
    print(f"{tag}: {len(entries)} implmap entries, {n_real} real, "
          f"{n_gen} fail-visible -> gen/{out_path}")
    return len(entries)


def main():
    total = 0
    total += generate("celeste.implmap", "real-fmod.txt",
                      "gen_fmod_failvisible.inc", "fmod", "mono_fmod_door.cpp")
    total += generate("steamworks.implmap", "real-steam.txt",
                      "gen_steam_failvisible.inc", "steam",
                      "mono_steam_door.cpp")
    print(f"total implmap entries covered: {total}")


if __name__ == "__main__":
    main()
